local ECSComponent = import("Frame.ECS.ECSComponent")

local UsableGoodDojo = import('Game.Dojo.UsableGoodDojo')

local CountDownTime = 2592000 --30 * 86400 30天的秒数

local CDTimerModule = CS.Engine.Modules.CDTimerModule
local TimeZoneUtils = CS.Engine.Http.TimeZoneUtils

---@class UsableGoodComponent
local UsableGoodComponent = Class("UsableGoodComponent", ECSComponent)

function UsableGoodComponent:__init()
    self.name = "UsableGoodComponent"
    ---@type table<string, UsableGoodDojo>
    self._usableGoods = {}
    self._countdown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if self._usableGoods and table.count(self._usableGoods) > 0 then
            for id, usableGoodDojos in pairs(self._usableGoods) do
                for k, v in pairs(usableGoodDojos) do
                    if isSet(v, "remainTime") then
                        v.remainTime = math.max(checkNumber(v.remainTime) - 1, 0)
                        if v.remainTime <= 0 then
                            ---过期时间
                            self:DeleteGoodsNo(v)
                        end
                    end
                end
            end
            --发送事件
            if Events.HasListener(Constants.EventNames.UIEventUsableGoodsTimeCountDown) then
                Events.Broadcast(Constants.EventNames.UIEventUsableGoodsTimeCountDown)
            end
        end
    end, CountDownTime, false, true)
end

function UsableGoodComponent:__delete()
    if not isNull(self._countdown) then
        CDTimerModule.GetInstance():RemoveCD(self._countdown)
        self._countdown = nil
    end
    self._usableGoods = nil
end

function UsableGoodComponent:Initial(jsonData)
    self._usableGoods = {}
    jsonData = checkTable(jsonData)
    ---@type UsableGoodDojo
    local usableGoodDojo = nil
    for id, data in pairs(jsonData) do
        usableGoodDojo = UsableGoodDojo.New()
        usableGoodDojo:Fill(data)
        self:UpdateGoodsNo(usableGoodDojo)
    end
end

---UpdateGoodsNo
---更新背包数据量 此处只用来内部获只给 GoodsUtils.DrawRewards 调用的
---@param usableGoodDojo UsableGoodDojo
function UsableGoodComponent:UpdateGoodsNo(usableGoodDojo)
    if not usableGoodDojo then return end

    --存在该配表id
    if self._usableGoods[checkString(usableGoodDojo.goodsId)] then
        local uGoods = self._usableGoods[checkString(usableGoodDojo.goodsId)]
        if not uGoods then
            uGoods = {}
        end

        --存在该id更新数量, 没有就添加
        if uGoods[checkString(usableGoodDojo.playerItemId)] then
            uGoods[checkString(usableGoodDojo.playerItemId)].num = uGoods[checkString(usableGoodDojo.playerItemId)].num + checkNumber(usableGoodDojo.num)
        else
            uGoods[checkString(usableGoodDojo.playerItemId)] = usableGoodDojo
        end
        --小于0直接置空
        if checkNumber(uGoods[checkString(usableGoodDojo.playerItemId)].num) <= 0 then
            uGoods[checkString(usableGoodDojo.playerItemId)] = nil
        end

        if table.count(self._usableGoods[checkString(usableGoodDojo.goodsId)]) <= 0 then
            self._usableGoods[checkString(usableGoodDojo.goodsId)] = nil
        end
    else
        self._usableGoods[checkString(usableGoodDojo.goodsId)] = {}
        self._usableGoods[checkString(usableGoodDojo.goodsId)][checkString(usableGoodDojo.playerItemId)] = usableGoodDojo
    end
    Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, checkInt(usableGoodDojo.goodsId))
end

---DeleteGoodsNo
---删除一个到期的物品
---@param usableGoodDojo UsableGoodDojo
function UsableGoodComponent:DeleteGoodsNo(usableGoodDojo)
    if not usableGoodDojo then return end

    if self._usableGoods[checkString(usableGoodDojo.goodsId)] then
        local uGoods = self._usableGoods[checkString(usableGoodDojo.goodsId)]
        if uGoods[checkString(usableGoodDojo.playerItemId)] then
            uGoods[checkString(usableGoodDojo.playerItemId)] = nil
            Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, checkInt(usableGoodDojo.goodsId)) 
        end

        if table.count(self._usableGoods[checkString(usableGoodDojo.goodsId)]) <= 0 then
            self._usableGoods[checkString(usableGoodDojo.goodsId)] = nil
        end
    end
end

---GetGoodsNo
---获取该配表id的总数量, 此处只用来内部获只给 GoodsUtils.GetThingNo 调用的, 这个获取该物品配表id对应的 所有期限的总数量
---@param goodsId number 配表id
function UsableGoodComponent:GetGoodsNo(goodsId)
    if isSet(self._usableGoods, checkString(goodsId)) then
        local t = self._usableGoods[checkString(goodsId)]

        local num = 0
        for k, v in pairs(t) do
            num = num + v.num
        end
        return checkNumber(num)
    end
    return 0
end

---GetGoodsNo
---获取该配表id 该服务器id 的数量
---@param goodsId number 配表id
---@param id number 服务器唯一id
function UsableGoodComponent:GetOneGoodsNo(goodsId, id)
    if not goodsId or not id then
        return 0
    end

    if isSet(self._usableGoods, checkString(goodsId)) then
        local t = self._usableGoods[checkString(goodsId)]
        local data = t[checkString(id)]
        if data then
            return checkNumber(data.num)
        end
    end
    return 0
end

---GetUsableGoods
---获取可使用道具的数据 排序后的, 按id和时间排序
function UsableGoodComponent:GetUsableGoods()
    local t = clone(self._usableGoods)
    return t
end

function UsableGoodComponent:GetUsableGoodsTab(goodsId)
    if not goodsId then 
        return nil
    end

    return self._usableGoods[checkString(goodsId)]
end

---GetUsableGoodsArray
---获取可使用道具的数组   ui显示用
---@return table[]
function UsableGoodComponent:GetUsableGoodsArray()
    local t = {}
    
    local allGoods = self:GetUsableGoods()
    for k, v in pairs(allGoods) do
        for m, n in pairs(v) do
            local item = {
                goodsId = k,
                num = self:GetOneGoodsNo(k, n.playerItemId),
                playerItemId = n.playerItemId,
                remainTime = checkNumber(n.remainTime)
            }
            table.insert(t, item)
        end
    end
    local ret = {}
    if #t > 0 then
        sortByKey(t, "goodsId")
        for i, v in pairs(t) do
            if v.remainTime > 0 then
                table.insert(ret, 1, v)
            else
                table.insert(ret, v)
            end
        end
        table.sort(ret, function(a, b)
            return checkNumber(a.remainTime) < checkNumber(b.remainTime)
        end)
    end
    return ret
end

---GetUsableGoodsArrayByGoodsId
---获取使用道具的数组
---@param goodsId integer @ 道具ID
---@return table[]
function UsableGoodComponent:GetUsableGoodsArrayByGoodsId(goodsId)
    local useGoodsKey = self:GetUsableGoodsTab(goodsId)
    local t = {}
    for m, n in pairs(useGoodsKey) do
        local item = {
            goodsId = goodsId,
            num = self:GetOneGoodsNo(goodsId, n.playerItemId),
            playerItemId = n.playerItemId,
            remainTime = checkNumber(n.remainTime)
        }
        table.insert(t, item)
    end
    table.sort(t, function(a, b)
        return checkNumber(a.remainTime) < checkNumber(b.remainTime)
    end)
    return t
end
-- 根据效果获取到可以使用的道具
function UsableGoodComponent:GetGoodShortestTimeByEffectType(effectType)
    local goodType = 0
    if checkInt(effectType)  == 504 then
        goodType = 69 
    end
    if goodType > 0 then
        local good = nil
        for id, usableGoodDojos in pairs(self._usableGoods) do
            for k, v in pairs(usableGoodDojos) do
               local oneGoodType = GoodsUtils.GetIdType(v.goodsId)
               if goodType == oneGoodType then
                    if not good then
                        good = v     
                    else 
                        if checkInt(v.remainTime) > 0 and checkInt(v.remainTime) < checkInt(good.remainTime)  then
                            good = v     
                        end    
                    end
               end
            end
            return good
        end
        
    end
end
function UsableGoodComponent:GetGoodsEffectType(effectType)
    local goodType = 0
    if checkInt(effectType)  == 504 then
        goodType = 69 
    end
    if goodType > 0 then
        local goods = {}
        for id, usableGoodDojos in pairs(self._usableGoods) do
            for k, v in pairs(usableGoodDojos) do
               local oneGoodType = GoodsUtils.GetIdType(v.goodsId)
               if goodType == oneGoodType then
                    goods = usableGoodDojos
                    break
               end
            end
            return goods
        end
        
    end
end
---GetUseGoods
---内部决定使用哪几个物品 
---@param goodsId number 配表id
function UsableGoodComponent:GetUseGoods(goodsId, num)
    goodsId = checkString(goodsId)
    num = checkNumber(num)

    local t = {}
    if num <= 0 then
        return t
    end
    local goods = self._usableGoods[goodsId]
    if goods then
        for k, v in pairs(goods) do            
            --如果不够
            if num > checkNumber(v.num) then
                table.insert(t, {
                    goodsId = v.goodsId, num = checkNumber(v.num), playerItemId = v.playerItemId
                })
                num = num - checkNumber(v.num)
            else
                table.insert(t, {
                    goodsId = v.goodsId, num = checkNumber(num), playerItemId = v.playerItemId
                })
                return t
            end
        end
    end
    return t
end

return UsableGoodComponent